    </div>

    <!-- Process steps -->
    <div class="process-grid" style="margin-bottom:40px">
      <div class="reveal reveal-d1" style="background:var(--color-onyx-black);border:1px solid var(--color-zinc-hairline);border-radius:var(--radius-xl);padding:20px;display:flex;flex-direction:column;gap:12px;transition:border-color 0.18s ease" onmouseenter="this.style.borderColor='var(--color-highlighter-lime)'" onmouseleave="this.style.borderColor='var(--color-zinc-hairline)'">
        <div style="display:flex;justify-content:space-between;align-items:center">
