      <div class="reveal reveal-d4" style="background:var(--color-onyx-black);border:1px solid var(--color-zinc-hairline);border-radius:var(--radius-xl);padding:20px;display:flex;flex-direction:column;gap:12px;transition:border-color 0.18s ease" onmouseenter="this.style.borderColor='var(--color-highlighter-lime)'" onmouseleave="this.style.borderColor='var(--color-zinc-hairline)'">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <div style="width:36px;height:36px;border-radius:var(--radius-md);background:var(--color-carbon);border:1px solid var(--color-zinc-hairline);display:flex;align-items:center;justify-content:center;fontSize:16px;color:var(--color-highlighter-lime)">✦</div>
          <span class="font-primary text-xs" style="color:var(--color-steel-gray);padding:3px 8px;border:1px solid var(--color-zinc-hairline);border-radius:var(--radius-full)">Travel dates</span>
        </div>
        <div>
          <p class="font-primary text-xs fw-medium uppercase ls-05" style="color:var(--color-ash-gray);margin-bottom:4px">Step 04</p>
          <h3 class="font-secondary text-lg fw-regular" style="color:var(--color-pure-white);margin-bottom:6px">Seamless Journey</h3>
          <p class="font-primary text-sm lh-16 text-muted">Your dedicated concierge is on standby 24/7. Ground transport, hotel check-ins, local guides, and permits are managed end-to-end.</p>
        </div>
      </div>
