    <!-- Philosophy + FAQ -->
    <div class="philosophy-grid">
      <!-- Philosophy -->
      <div class="reveal-scale" style="background:var(--color-carbon);border:1px solid var(--color-zinc-hairline);border-radius:var(--radius-xl);padding:24px;display:flex;flex-direction:column;gap:20px">
        <div>
          <p class="font-primary text-xs fw-medium uppercase ls-1" style="color:var(--color-ash-gray);margin-bottom:12px">Our philosophy</p>
          <h3 class="heading-md" style="margin-bottom:12px">Curating divine pilgrimages &amp;<br>tours with absolute responsibility.</h3>
          <p class="font-primary text-sm lh-17 text-muted">Shivalay Travels brings premium coordination standards to Indian domestic tourism. We coordinate directly with local teams, select verified hotels, and maintain round-the-clock support.</p>
        </div>
        <div style="border-top:1px solid var(--color-zinc-hairline);padding-top:18px;display:flex;flex-direction:column;gap:12px">
          <div style="display:flex;gap:10px;align-items:flex-start">
            <span class="text-xs" style="color:var(--color-highlighter-lime);margin-top:2px;flex-shrink:0">✦</span>
            <div>
              <p class="font-primary fs-13 fw-medium lh-13" style="color:var(--color-pure-white)">Taj, Oberoi &amp; boutique stays</p>
              <p class="font-primary fs-11 text-muted" style="margin-top:2px">Curated premium accommodations</p>
            </div>
          </div>
          <div style="display:flex;gap:10px;align-items:flex-start">
            <span class="text-xs" style="color:var(--color-highlighter-lime);margin-top:2px;flex-shrink:0">✦</span>
            <div>
              <p class="font-primary fs-13 fw-medium lh-13" style="color:var(--color-pure-white)">All permits &amp; logistics handled</p>
              <p class="font-primary fs-11 text-muted" style="margin-top:2px">Inner Line Permits &amp; border paperwork</p>
            </div>
          </div>
          <div style="display:flex;gap:10px;align-items:flex-start">
            <span class="text-xs" style="color:var(--color-highlighter-lime);margin-top:2px;flex-shrink:0">✦</span>
            <div>
              <p class="font-primary fs-13 fw-medium lh-13" style="color:var(--color-pure-white)">Local expert guides only</p>
              <p class="font-primary fs-11 text-muted" style="margin-top:2px">Regional culture &amp; terrain specialists</p>
            </div>
